import {icon,money,badge,pageHeading,statCard,escapeHTML as esc} from './ui.js';
import {calculate,evaluateRemote} from './engine.js';
import {bindValidatedForm,validateLoan} from './validation.js';
let step=1,editingId=null,selectedLoan=null;
const descriptions=['For the milestones, and everything in between.','A helping hand for your everyday needs.','A little support for the here and now.','Flexible support from your cooperative.','Get moving toward your next destination.','Make a little more room for comfort.','Put your health and peace of mind first.','Bring your balances into clearer focus.','The tools to do your best work.','A bigger step toward your future.'];
const productIcons=['bank','leaf','clock','briefcase','arrow-up-right','wallet','shield','receipt','document','bank'];
const displayDate=v=>new Date(v+'T12:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'});
const myLoans=c=>c.state.loans.filter(l=>l.memberId===c.member.id&&l.status==='Active'&&l.balance>0);
const myApps=c=>c.state.applications.filter(a=>a.memberId===c.member.id);
const myTransactions=c=>c.state.transactions.filter(t=>t.memberId===c.member.id);
function defaults(c){return {product:'Regular loan',amount:50000,term:12,income:c.member.income||42000,liabilities:4500,savings:c.member.savings||0,repayment:95,comakerName:'Andrea Mendoza',comakerIncome:38000,comakerLiabilities:3000,purpose:'',method:'fixed',annualRate:c.state.config.annualRate,serviceRate:c.state.config.serviceRate};}
function inputs(c){return {...defaults(c),...(c.state.draft||{}),annualRate:c.state.config.annualRate,serviceRate:c.state.config.serviceRate};}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 350 230" fill="none" aria-hidden="true"><circle cx="220" cy="130" r="125" stroke="#93B37B" stroke-opacity=".12"/><circle cx="220" cy="130" r="100" stroke="#93B37B" stroke-opacity=".17"/><circle cx="220" cy="130" r="74" stroke="#93B37B" stroke-opacity=".2"/><path d="M140 198h127M158 197v-32h93v32" stroke="#8BA776" stroke-opacity=".6"/><path d="M204 166v-76" stroke="#B7CE96" stroke-width="2"/><path d="M204 142c-31 0-45-16-45-38 28 0 45 10 45 38Z" fill="#96B87C"/><path d="M205 122c29 0 41-17 41-37-26 0-41 11-41 37Z" fill="#CDDCAB"/><path d="M204 103c-17 0-29-12-29-28 21 0 29 12 29 28Z" fill="#759B63"/><rect x="178" y="163" width="52" height="40" rx="5" fill="#D1DFAD"/><path d="m183 163 5 39m31-39-5 39" stroke="#B2C592"/><circle cx="276" cy="160" r="24" fill="#749964"/><circle cx="276" cy="160" r="17" stroke="#B4CA95" stroke-width=".8"/><path d="M271 170v-20h6a5 5 0 0 1 0 10h-10m0-6h15" stroke="#D3E2B2" stroke-width="1.3"/><circle cx="125" cy="141" r="16" stroke="#86A76D" stroke-width="1.3"/><path d="m120 141 4 4 7-8" stroke="#A3BF87"/><path d="M272 63v12m-6-6h12M134 78v8m-4-4h8" stroke="#9DBB81" stroke-width="1.2"/><circle cx="300" cy="113" r="2" fill="#AAC28B"/><circle cx="147" cy="185" r="2" fill="#AAC28B"/></svg>`;}
export function renderMember(view,c){switch(view){case'overview':return dashboard(c);case'applications':return applications(c);case'apply':return applicationWizard(c);case'loans':return loansPage(c);case'payments':return payments(c);case'calculator':return calculator(c);default:return dashboard(c);}}
function dashboard(c){const loans=myLoans(c),apps=myApps(c),pending=apps.filter(a=>['Pending','Verified','Evaluated','Needs revision'].includes(a.status)),balance=loans.reduce((s,l)=>s+l.balance,0),due=loans.reduce((s,l)=>s+l.monthly,0);return pageHeading(`Good morning, ${esc(c.member.name.split(' ')[0])} <span aria-hidden="true">☀</span>`,'A clear view of your finances.','A little peace of mind. Everything you need, right here.',`<button class="btn btn-primary" data-new-application>${icon('plus')} New application</button>`)+
`<section class="hero-banner"><div class="hero-copy"><div class="hero-kicker">${icon('leaf')} Growing together, since 1991</div><h2>Built around your next chapter.</h2><p>Big plans or everyday needs, your cooperative is here to help you take the next step.</p><button class="hero-link" data-nav="calculator">Explore your loan options ${icon('arrow-right')}</button></div>${heroArt()}<div class="hero-annotation">YOUR FUTURE, OUR SHARED PURPOSE</div></section>
<div class="stat-grid">${statCard('Outstanding balance',money(balance),'wallet','Across your active loans')}${statCard('Active loans',`${loans.length.toString().padStart(2,'0')} <small>loans</small>`,'document',`<span class="positive">${icon('check-circle')} All payments on track</span>`)}${statCard('Share capital',money(c.member.savings),'bank','Your contribution to our growth')}${statCard('Next payment',money(due),'calendar',due?'Due October 30, 2026':'No scheduled payment')}</div>
<div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Your active loans</h2><p class="panel-subtitle">Little by little, moving forward.</p></div><button class="btn-link" data-nav="loans">View all loans ${icon('arrow-right')}</button></div>${loans.length?loanTable(loans):`<div class="empty-state">${icon('wallet')}<p>Your active loans will appear here.</p><button class="btn btn-light" data-new-application>Explore loan options</button></div>`}<div class="table-bottom"><span>${loans.length} active loans · Updated October 23, 2026</span><span>${icon('shield')} Secure member records</span></div></section>
<section class="panel next-payment"><div class="panel-head"><h2>Your next payment</h2><span class="due-tag">${due?'In 7 days':'All clear'}</span></div><div class="panel-body"><div class="money-display">${money(due)}<small>PHP</small></div><div class="payment-date">${icon('calendar')} Friday, October 30, 2026</div><div class="payment-details">${loans.map(l=>`<div class="metric-row"><span>${esc(l.product)}</span><strong>${money(l.monthly)}</strong></div>`).join('')}<div class="metric-row"><span>Payment method</span><strong>Salary deduction</strong></div></div><button class="btn btn-light w-100" data-nav="payments">View payment schedule ${icon('arrow-right')}</button><div class="auto-deduct">${icon('shield')} Automatically deducted. One less thing to think about.</div></div></section></div>
<div class="content-grid"><section class="panel chart-panel"><div class="panel-head"><div><h2>Your repayment journey</h2><p class="panel-subtitle">Every payment is a step closer.</p></div><span class="chart-period">Last 6 months ${icon('chevron-down')}</span></div><div class="chart-wrap"><div class="d-flex justify-content-end chart-legend mb-3"><span><i class="legend-dot"></i>Loan balance</span><span><i class="legend-dot light"></i>Share capital</span></div>${balance?balanceChart():`<div class="empty-state"><p>Your repayment journey will appear when you have an active loan.</p></div>`}</div></section>
<section class="panel"><div class="panel-head"><h2>A little activity update</h2><button class="btn-link" data-nav="payments">View all ${icon('arrow-right')}</button></div><div class="activity-list">${pending.length?`<div class="activity-item"><span class="activity-icon">${icon('document')}</span><div><strong>Application submitted</strong><p>${esc(pending[0].product)} · ${money(pending[0].amount)}</p></div><span class="activity-time">Oct 22</span></div>`:''}${myTransactions(c).slice(0,2).map(t=>`<div class="activity-item"><span class="activity-icon">${icon('check')}</span><div><strong>Payment received</strong><p>${money(t.amount)} · ${esc(t.method)}</p></div><span class="activity-time">${displayDate(t.date).replace(', 2026','')}</span></div>`).join('')}${!pending.length&&!myTransactions(c).length?'<div class="empty-state"><p>You’re all caught up.</p></div>':''}</div></section></div>
<aside class="announcement">${icon('bank')}<div><strong>A cooperative that grows with you.</strong><p>Explore 10 loan facilities designed around the needs of our members.</p></div><button class="btn-link" data-new-application>Find your next step ${icon('arrow-up-right')}</button></aside>`;}
function loanTable(loans){return `<div class="table-responsive"><table class="data-table"><thead><tr><th>LOAN DETAILS</th><th>OUTSTANDING</th><th>REPAID</th><th>STATUS</th><th></th></tr></thead><tbody>${loans.map(l=>`<tr><td><div class="loan-cell"><span class="stat-icon">${icon(l.product==='Laptop loan'?'document':'bank')}</span><div><strong>${esc(l.product)}</strong><small>${esc(l.id)}</small></div></div></td><td><strong>${money(l.balance)}</strong><div class="muted" style="font-size:8px;margin-top:4px">of ${money(l.amount)}</div></td><td><span style="font-size:9px">${Math.round((1-l.balance/l.amount)*100)}%</span><div class="loan-progress"><span style="width:${(1-l.balance/l.amount)*100}%"></span></div></td><td>${badge(l.status)}</td><td><button class="icon-btn" data-loan="${l.id}" aria-label="View ${esc(l.product)}">${icon('chevron-right')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function balanceChart(){return `<svg class="chart-svg" role="img" aria-label="Illustrative loan balance decreases from 156,000 pesos in May to 124,500 in October. Share capital grows from 50,000 to 62,500 pesos." viewBox="0 0 620 172"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9eb88b" stop-opacity=".15"/><stop offset="1" stop-color="#9eb88b" stop-opacity="0"/></linearGradient></defs><g stroke="#edf0e8" stroke-dasharray="3 4"><path d="M47 20h555M47 59h555M47 98h555M47 137h555"/></g><g><text x="0" y="23">₱160k</text><text x="0" y="62">₱120k</text><text x="7" y="101">₱80k</text><text x="7" y="140">₱40k</text></g><path d="M50 27C90 30 120 35 155 39S229 48 265 49 338 59 375 62 450 68 485 72 559 78 595 83V140H50Z" fill="url(#chart-fill)"/><path d="M50 27C90 30 120 35 155 39S229 48 265 49 338 59 375 62 450 68 485 72 559 78 595 83" fill="none" stroke="#789568" stroke-width="2.3"/><path d="M50 127C100 125 120 124 155 123S230 120 265 118 340 116 375 115 450 111 485 110 560 106 595 105" fill="none" stroke="#c4d4ac" stroke-width="2" stroke-dasharray="4 4"/><circle cx="595" cy="83" r="4" fill="#789568" stroke="#fff" stroke-width="2"/><g><text x="42" y="165">May</text><text x="145" y="165">Jun</text><text x="256" y="165">Jul</text><text x="365" y="165">Aug</text><text x="475" y="165">Sep</text><text x="585" y="165">Oct</text></g></svg>`;}
function applications(c){const apps=myApps(c);return pageHeading('Your next steps','My applications','Follow every step, from your first idea to the final decision.',`<button class="btn btn-primary" data-new-application>${icon('plus')} New application</button>`)+`<div class="info-banner">${icon('document')}<span>Pending applications can still be edited. After verification, your cooperative takes care of the next steps.</span></div><section class="panel"><div class="panel-head"><h2>Application history <span class="muted ms-2">${apps.length}</span></h2><label class="visually-hidden" for="application-filter">Application status</label><select id="application-filter" class="form-select" style="width:auto;font-size:10px;padding:6px 25px 6px 10px"><option>All statuses</option><option>Pending</option><option>Verified</option><option>Evaluated</option><option>Approved</option><option>Rejected</option><option>Needs revision</option></select></div><div class="table-responsive"><table class="data-table"><thead><tr><th>APPLICATION</th><th>AMOUNT / TERM</th><th>SUBMITTED</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody id="member-app-rows">${applicationRows(apps)}</tbody></table></div>${!apps.length?'<div class="empty-state"><h3>Your next chapter starts here.</h3><p>When you apply for a loan, you can track its progress here.</p></div>':''}</section><section class="panel"><div class="panel-head"><h2>What happens after you apply?</h2></div><div class="panel-body"><div class="row g-4">${[['document','Application received','Your details are saved for the staff.'],['shield','Staff verification','Your information and documents are checked.'],['activity','Credit evaluation','A simple BRB gives advisory guidance.'],['check-circle','Final decision','The Chairman or Vice Chairman decides.']].map(([i,t,d],n)=>`<div class="col-6 col-lg-3"><span class="stat-icon mb-3">${icon(i)}</span><h3 style="font-size:11px;font-weight:650">${n+1}. ${t}</h3><p class="muted" style="font-size:10px;line-height:1.8">${d}</p></div>`).join('')}</div></div></section>`;}
function applicationRows(apps){return apps.map(a=>`<tr><td><strong>${esc(a.product)}</strong><div class="muted mt-1" style="font-size:8px">${esc(a.id)}</div></td><td><strong>${money(a.amount)}</strong><div class="muted mt-1" style="font-size:8px">${a.term} months</div></td><td>${displayDate(a.date)}</td><td>${badge(a.status)}</td><td><div class="d-flex gap-3"><button class="btn-link" data-track="${a.id}">Track ${icon('arrow-right')}</button>${['Pending','Needs revision'].includes(a.status)?`<button class="btn-link" data-edit-application="${a.id}">Edit</button>`:''}</div></td></tr>`).join('');}
function applicationWizard(c){const d=inputs(c),calc=safeEstimate(d);return pageHeading('One step toward what’s next',editingId?'Update your application.':'Let’s make your next step happen.','A few details today. A little more possibility tomorrow.')+`<div class="stepper">${['Choose a loan','Your details','Review & submit'].map((l,i)=>`<div class="step ${step===i+1?'active':step>i+1?'complete':''}"><span class="step-number">${step>i+1?icon('check'):i+1}</span>${l}</div>`).join('')}</div>`+(step===1?`<div class="d-flex align-items-center justify-content-between mb-3"><h2 class="section-title">A loan for every chapter.</h2><span class="muted" style="font-size:9px">10 facilities · Sample rates</span></div><div class="product-grid">${c.products.map((p,i)=>`<button class="product-option ${d.product===p?'selected':''}" data-product="${esc(p)}">${d.product===p?`<span class="product-selected">${icon('check-circle')}</span>`:''}<span class="stat-icon">${icon(productIcons[i])}</span><h3>${esc(p)}</h3><p>${descriptions[i]}</p><small>Illustrative rate · ${c.state.config.annualRate}% p.a. ${icon('arrow-up-right')}</small></button>`).join('')}</div><div class="form-actions"><button class="btn btn-light" data-nav="applications">Cancel</button><button class="btn btn-primary" id="wizard-next">Continue with ${esc(d.product)} ${icon('arrow-right')}</button></div>`:step===2?`<div class="content-grid"><section class="panel"><div class="panel-head"><h2>Tell us a little more.</h2>${badge('Draft')}</div><form class="panel-body" id="loan-details-form" aria-describedby="loan-form-help">
<p id="loan-form-help" class="muted text-small mb-4">Complete all 10 required fields using fictional information. Sample loan limits are shown below each field. Fields marked <span aria-hidden="true">*</span><span class="visually-hidden">with an asterisk</span> are required.</p>
<div class="form-error-summary" data-error-summary hidden tabindex="-1" role="alert"></div>
<fieldset class="border-0 p-0 m-0"><legend class="section-title mb-4">Loan details</legend><div class="form-grid">
${numberField('amount','Loan amount (PHP)',d.amount,1000,2000000,100,'Enter ₱1,000 to ₱2,000,000 in multiples of ₱100. These are sample limits.')}
<div class="field" data-field="term"><label class="form-label" for="term">Repayment term <span aria-hidden="true">*</span></label><select class="form-select" id="term" name="term" aria-describedby="term-help" required>${[6,12,18,24,36,48,60].map(t=>`<option value="${t}" ${Number(d.term)===t?'selected':''}>${t} months</option>`).join('')}</select><div id="term-help" class="form-text">Choose one sample term: 6, 12, 18, 24, 36, 48 or 60 months.</div></div>
<div class="field" data-field="purpose" style="grid-column:1/-1"><label class="form-label" for="purpose">What will you use the loan for? <span aria-hidden="true">*</span></label><input class="form-control" type="text" id="purpose" name="purpose" minlength="5" maxlength="180" required aria-describedby="purpose-help" placeholder="e.g. Home improvements" value="${esc(d.purpose)}"><div id="purpose-help" class="form-text">Describe the fictional purpose in 5 to 180 characters.</div></div>
</div></fieldset><hr class="my-4" style="border-color:#dfe7d9">
<fieldset class="border-0 p-0 m-0"><legend class="section-title mb-4">Your financial snapshot</legend><div class="form-grid">
${numberField('income','Monthly income (PHP)',d.income,1,10000000,0.01,'Enter ₱1 to ₱10,000,000 per month, with up to 2 decimal places.')}
${numberField('liabilities','Existing monthly payments (PHP)',d.liabilities,0,10000000,0.01,'Enter ₱0 to ₱10,000,000 in existing monthly obligations.')}
${numberField('savings','Share capital / savings (PHP)',d.savings,0,10000000,0.01,'Enter ₱0 to ₱10,000,000 in fictional cooperative savings.')}
${numberField('repayment','On-time payment history (%)',d.repayment,0,100,1,'Enter a whole percentage from 0 to 100. Use 95 for this demonstration.')}
</div></fieldset><hr class="my-4" style="border-color:#dfe7d9">
<fieldset class="border-0 p-0 m-0"><legend class="section-title mb-4">Your co-maker</legend>
<div class="field" data-field="comakerName"><label class="form-label" for="comakerName">Co-maker name <span aria-hidden="true">*</span></label><input class="form-control" type="text" id="comakerName" name="comakerName" value="${esc(d.comakerName)}" minlength="2" maxlength="70" required aria-describedby="comakerName-help" autocomplete="off"><div id="comakerName-help" class="form-text">Use a fictional co-maker name, 2 to 70 characters long.</div></div><div class="form-grid">
${numberField('comakerIncome','Co-maker monthly income (PHP)',d.comakerIncome,1,10000000,0.01,'Enter ₱1 to ₱10,000,000 per month for the fictional co-maker.')}
${numberField('comakerLiabilities','Co-maker monthly payments (PHP)',d.comakerLiabilities,0,10000000,0.01,'Enter ₱0 to ₱10,000,000 in the co-maker’s monthly obligations.')}
</div></fieldset><div class="form-actions flex-wrap"><button class="btn btn-light" type="button" id="wizard-back">Back</button><button class="btn btn-light" type="reset">Restore draft values</button><button class="btn btn-primary" type="submit">Review application ${icon('arrow-right')}</button></div></form></section><div><div id="loan-live-estimate">${estimateCard(d,calc)}</div><div class="info-banner">${icon('shield')}<span>Use fictional information. All rates, limits, and rules in this prototype are illustrative.</span></div></div></div>`:`<div class="content-grid"><section class="panel"><div class="panel-head"><h2>A quick look before you send.</h2>${badge('Ready to review')}</div><div class="panel-body"><dl class="summary-list">${[['Applicant',c.member.name],['Member ID',c.member.id],['Loan facility',d.product],['Loan amount',money(d.amount)],['Repayment term',d.term+' months'],['Purpose',d.purpose],['Monthly income',money(d.income)],['Existing monthly payments',money(d.liabilities)],['Share capital / savings',money(d.savings)],['On-time payment history',d.repayment+'%'],['Co-maker',d.comakerName],['Co-maker monthly income',money(d.comakerIncome)],['Co-maker monthly payments',money(d.comakerLiabilities)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="info-banner mt-4 mb-3">${icon('activity')}<span>An initial advisory check runs on submission. Staff will verify your details and review the recommendation. Final approval remains with the Chairman or Vice Chairman.</span></div><form id="submit-application-form"><div class="form-check mb-4"><input class="form-check-input" type="checkbox" id="application-consent" required><label class="form-check-label text-small" for="application-consent">I confirm these are fictional details for this prototype.</label></div><div class="form-actions"><button class="btn btn-light" type="button" id="wizard-back">Back to details</button><button class="btn btn-primary" type="submit" id="submit-application">${icon('check')} ${editingId?'Save changes':'Submit application'}</button></div></form></div></section>${estimateCard(d,calc)}</div>`);}
function numberField(name,label,value,min=0,max=10000000,stepValue=0.01,help=''){
  const helpText=help||`Enter a number from ${min.toLocaleString('en-PH')} to ${max.toLocaleString('en-PH')}${stepValue===1?', using whole numbers':', with up to 2 decimal places'}.`;
  return `<div class="field" data-field="${name}"><label class="form-label" for="${name}">${label} <span aria-hidden="true">*</span></label><input class="form-control" id="${name}" name="${name}" type="number" min="${min}" max="${max}" step="${stepValue}" value="${esc(value)}" required aria-describedby="${name}-help"><div id="${name}-help" class="form-text">${helpText}</div></div>`;
}
function safeEstimate(d){try{return calculate(d);}catch{return null;}}
function manilaToday(){const parts=new Intl.DateTimeFormat('en',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(name=>parts.find(p=>p.type===name).value).join('-');}
function estimateCard(d,calc){if(!calc)return `<section class="panel next-payment"><div class="panel-head"><h2>Your loan estimate</h2>${icon('chart')}</div><div class="panel-body"><p class="muted text-small mb-0">Complete the numeric fields within the sample limits to see your estimated payment.</p></div></section>`;return `<section class="panel next-payment"><div class="panel-head"><h2>Your loan estimate</h2>${icon('chart')}</div><div class="panel-body"><span class="pill green mb-3">${esc(d.product)}</span><dl class="summary-list"><div><dt>Loan amount</dt><dd>${money(d.amount)}</dd></div><div><dt>Term</dt><dd>${d.term} months</dd></div><div><dt>Sample annual rate</dt><dd>${d.annualRate}%</dd></div><div><dt>Interest method</dt><dd>${d.method==='diminishing'?'Diminishing':'Fixed / flat'}</dd></div><div><dt>Total interest</dt><dd id="estimate-interest">${money(calc.interest)}</dd></div><div><dt>Service fee (${d.serviceRate}%)</dt><dd id="estimate-fee">${money(calc.fee)}</dd></div><div><dt>Net proceeds</dt><dd id="estimate-net">${money(calc.netProceeds)}</dd></div></dl><div class="summary-total"><small>Estimated monthly payment</small><strong id="estimate-monthly">${money(calc.monthlyPayment)}</strong></div><p class="muted mt-3 mb-0" style="font-size:9px;line-height:1.8">Illustrative amounts only. The service fee is deducted from proceeds. Final terms are subject to cooperative review.</p></div></section>`;}
function loansPage(c){const loans=myLoans(c);return pageHeading('One step closer, every month','My loans','Your balances, repayment progress, and the road ahead.',`<button class="btn btn-light" data-nav="calculator">${icon('chart')} Loan calculator</button>`)+`<div class="stat-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${statCard('Total borrowed',money(loans.reduce((s,l)=>s+l.amount,0)),'bank','Across your active loans')}${statCard('Principal repaid',money(loans.reduce((s,l)=>s+l.amount-l.balance,0)),'check-circle','Progress worth feeling good about')}${statCard('Remaining balance',money(loans.reduce((s,l)=>s+l.balance,0)),'wallet','A little closer with every payment')}</div>${loans.map(l=>`<section class="panel"><div class="panel-head"><div class="loan-cell"><span class="stat-icon">${icon(l.product==='Laptop loan'?'document':'bank')}</span><div><h2>${esc(l.product)}</h2><p class="panel-subtitle">${l.id}</p></div></div>${badge(l.status)}</div><div class="panel-body"><div class="row g-4"><div class="col-6 col-lg-3"><p class="muted text-small">Outstanding balance</p><h3 style="font-size:24px;font-weight:750;letter-spacing:-1px">${money(l.balance)}</h3></div><div class="col-6 col-lg-3"><p class="muted text-small">Monthly payment</p><h3 style="font-size:20px;font-weight:650">${money(l.monthly)}</h3></div><div class="col-6 col-lg-3"><p class="muted text-small">Repayment progress</p><strong>${Math.round((1-l.balance/l.amount)*100)}%</strong><div class="progress mt-2"><div class="progress-bar" style="width:${(1-l.balance/l.amount)*100}%"></div></div></div><div class="col-6 col-lg-3 d-flex align-items-center justify-content-lg-end"><button class="btn btn-light" data-loan="${l.id}">View loan details ${icon('arrow-right')}</button></div></div></div></section>`).join('')}${!loans.length?'<section class="panel empty-state"><h3>A fresh start.</h3><p>You do not have any active loans yet.</p><button class="btn btn-primary" data-new-application>Apply for a loan</button></section>':''}`;}
function payments(c){const transactions=myTransactions(c),loans=myLoans(c);return pageHeading('Every payment, accounted for','Payments & ledger','A transparent view of your payments and upcoming deductions.',`<button class="btn btn-light" data-statement>${icon('document')} View statement</button>`)+`<div class="info-banner">${icon('shield')}<span>Payments are collected through salary deduction or recorded by staff over the counter. No online payment is required here.</span></div><div class="stat-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${statCard('Next salary deduction',money(loans.reduce((s,l)=>s+l.monthly,0)),'calendar','October 30, 2026')}${statCard('Payments this month',money(transactions.filter(t=>t.date.startsWith('2026-10')).reduce((s,t)=>s+t.amount,0)),'check-circle','Recorded in your member ledger')}${statCard('Payment method','Salary deduction','briefcase','Handled by your cooperative')}</div><section class="panel"><div class="panel-head"><h2>Payment history</h2><span class="pill green">${transactions.length} transactions</span></div><div class="table-responsive"><table class="data-table"><thead><tr><th>TRANSACTION</th><th>DATE</th><th>LOAN</th><th>METHOD</th><th>AMOUNT</th><th>STATUS</th></tr></thead><tbody>${transactions.map(t=>`<tr><td><strong>${t.id}</strong></td><td>${displayDate(t.date)}</td><td>${esc(t.loanId)}</td><td>${esc(t.method)}</td><td><strong>${money(t.amount)}</strong></td><td>${badge(t.status)}</td></tr>`).join('')}</tbody></table></div>${!transactions.length?'<div class="empty-state"><p>Your posted payments will appear here.</p></div>':''}</section><section class="panel"><div class="panel-head"><h2>Upcoming payment schedule</h2><span class="muted text-small">Illustrative · next 3 deductions</span></div><div class="table-responsive"><table class="data-table"><thead><tr><th>PAYMENT DATE</th>${loans.map(l=>`<th>${esc(l.product).toUpperCase()}</th>`).join('')}<th>TOTAL DUE</th><th>METHOD</th></tr></thead><tbody>${['2026-10-30','2026-11-30','2026-12-30'].map(d=>`<tr><td>${displayDate(d)}</td>${loans.map(l=>`<td>${money(l.monthly)}</td>`).join('')}<td><strong>${money(loans.reduce((s,l)=>s+l.monthly,0))}</strong></td><td>Salary deduction</td></tr>`).join('')}</tbody></table></div></section>`;}
function calculator(c){const d=inputs(c);return pageHeading('Plan with a little more clarity','Find a payment that feels right.','Explore a few possibilities before you take the next step.')+`<div class="content-grid"><section class="panel"><div class="panel-head"><h2>Loan calculator</h2>${icon('chart')}</div><form id="calculator-form" class="panel-body"><div class="field"><label class="form-label" for="calc-product">Loan facility</label><select id="calc-product" name="product" class="form-select">${c.products.map(p=>`<option ${p===d.product?'selected':''}>${p}</option>`).join('')}</select></div><div class="form-grid">${numberField('amount','Loan amount (PHP)',d.amount,1000,2000000)}<div class="field"><label class="form-label" for="term">Repayment term</label><select class="form-select" id="term" name="term">${[6,12,18,24,36,48,60].map(v=>`<option value="${v}" ${Number(d.term)===v?'selected':''}>${v} months</option>`).join('')}</select></div></div><div class="field mt-4"><label class="form-label" for="method">Interest calculation</label><select class="form-select" id="method" name="method"><option value="fixed" ${d.method==='fixed'?'selected':''}>Fixed / flat interest</option><option value="diminishing" ${d.method==='diminishing'?'selected':''}>Diminishing balance</option></select></div><div class="info-banner mb-4">${icon('help')}<span>Fixed interest uses the original loan amount for the whole term. Diminishing interest uses the remaining principal balance.</span></div><button class="btn btn-primary" type="submit">Calculate estimate ${icon('arrow-right')}</button><button class="btn btn-light ms-2" type="button" id="use-estimate">Use for application</button></form></section><div id="calculator-estimate">${estimateCard(d,safeEstimate(d))}</div></div>`;}
function trackApplication(a,c){const stages=[['Submitted','We received your application.'],['Staff verification','The cooperative checks your details.'],['Credit evaluation','An advisory recommendation supports review.'],['Final decision','Chairman / Vice Chairman review.']];const stage=['Approved','Rejected'].includes(a.status)?4:a.status==='Evaluated'?3:a.verified?2:1;c.openModal('Your application journey',`<div class="d-flex justify-content-between align-items-center mb-4"><div><h3 class="section-title mb-2">${esc(a.product)} · ${money(a.amount)}</h3><span class="muted text-small">${esc(a.id)} · ${a.term} months</span></div>${badge(a.status)}</div>${a.status==='Needs revision'?`<div class="info-banner">${icon('document')}<span>Staff requested a revision: ${esc(a.revisionReason||'Review your application details and resubmit.')}</span></div>`:''}<div class="timeline">${stages.map(([t,d],i)=>`<div class="timeline-step ${i<stage?'done':''} ${i===stage?'current':''}"><span class="timeline-point">${icon(i<stage?'check':'clock')}</span><div><h4>${t}</h4><p>${d}</p></div></div>`).join('')}</div>${a.evaluation?`<div class="info-banner">${icon('activity')}<span>Advisory evaluation: <strong>${a.evaluation.score}/100 · ${esc(a.evaluation.recommendation)}</strong>. This recommendation does not decide your application.</span></div>`:''}${a.decisionReason?`<p class="text-small muted">${esc(a.decisionBy||'Chairman')}: ${esc(a.decisionReason)}</p>`:''}`,`<button class="btn btn-primary" data-close-modal>Got it</button>`);}
function loanDetails(l,c){selectedLoan=l.id;c.openModal(l.product,`<div class="d-flex justify-content-between mb-3"><span class="muted text-small">${l.id}</span>${badge(l.status)}</div><dl class="summary-list">${[['Original principal',money(l.amount)],['Outstanding principal',money(l.balance)],['Monthly payment',money(l.monthly)],['Sample annual rate',l.rate+'%'],['Term',l.term+' months'],['Next payment',displayDate(l.nextDate)],['Payment method','Salary deduction']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><p class="muted text-small mt-4">This is a sample account for demonstrating the member experience. View Payments & ledger for the posted transactions.</p>`,`<button class="btn btn-light" data-close-modal>Close</button><button class="btn btn-primary" id="loan-to-ledger">View ledger ${icon('arrow-right')}</button>`);document.querySelector('#loan-to-ledger').onclick=()=>{c.closeModal();c.navigate('payments');};}
function formInput(form,d){for(const [k,v] of new FormData(form)){d[k]=['amount','term','income','liabilities','savings','repayment','comakerIncome','comakerLiabilities'].includes(k)?Number(v):String(v).trim();}return d;}
export function bindMember(view,c){document.querySelectorAll('[data-new-application]').forEach(b=>b.onclick=()=>{step=1;editingId=null;c.state.draft=defaults(c);c.save();c.navigate('apply');});document.querySelectorAll('[data-loan]').forEach(b=>b.onclick=()=>loanDetails(myLoans(c).find(l=>l.id===b.dataset.loan),c));
 const appBindings=()=>{document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>trackApplication(myApps(c).find(a=>a.id===b.dataset.track),c));document.querySelectorAll('[data-edit-application]').forEach(b=>b.onclick=()=>{const a=myApps(c).find(a=>a.id===b.dataset.editApplication);if(!['Pending','Needs revision'].includes(a.status))return;editingId=a.id;step=2;c.state.draft=Object.fromEntries(Object.entries(defaults(c)).map(([k,v])=>[k,a[k]??v]));c.navigate('apply');});};appBindings();
 const filter=document.querySelector('#application-filter');if(filter)filter.onchange=()=>{document.querySelector('#member-app-rows').innerHTML=applicationRows(myApps(c).filter(a=>filter.value==='All statuses'||a.status===filter.value));appBindings();};
 document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>{c.state.draft={...inputs(c),product:b.dataset.product};c.save();c.render();});
 const details=document.querySelector('#loan-details-form');
 let detailsValidation=null;
 if(details){
   const updateEstimate=()=>{
     const d=formInput(details,inputs(c));
     const numericValid=[...details.querySelectorAll('input[type="number"],select')].every(field=>field.checkValidity());
     const output=document.querySelector('#loan-live-estimate');
     if(output)output.innerHTML=estimateCard(d,numericValid?safeEstimate(d):null);
   };
   detailsValidation=bindValidatedForm(details,{
     validate:validateLoan,
     onValid(){c.state.draft=formInput(details,inputs(c));step=3;c.save();c.render();},
     onReset:updateEstimate,
   });
   details.addEventListener('input',updateEstimate);
   details.addEventListener('change',updateEstimate);
 }
 const next=document.querySelector('#wizard-next');if(next)next.onclick=()=>{step=2;c.render();};
 const back=document.querySelector('#wizard-back');if(back)back.onclick=()=>{
   if(details&&detailsValidation&&!Object.keys(detailsValidation.validate()).length)c.state.draft=formInput(details,inputs(c));
   step--;c.save();c.render();
 };
 const submit=document.querySelector('#submit-application-form');if(submit)submit.onsubmit=async e=>{e.preventDefault();const button=document.querySelector('#submit-application');button.disabled=true;button.textContent='Running initial check…';try{const d=inputs(c),evaluation=await evaluateRemote(d);const old=editingId?c.state.applications.find(a=>a.id===editingId):null;const id=old?.id||'APP-2026-'+String(Math.max(128,...c.state.applications.map(a=>Number(a.id.split('-').at(-1))||0))+1).padStart(4,'0');const application={...d,id,memberId:c.member.id,memberName:c.member.name,initials:c.member.initials,date:manilaToday(),status:'Pending',verified:false,evaluation:null,comakerEvaluation:null,initialEvaluation:evaluation,revisionReason:'',decisionReason:'',reviewer:'',decisionBy:''};if(old)Object.assign(old,application);else c.state.applications.unshift(application);c.addAudit(editingId?'Application updated':'Application submitted',`${id} · ${d.product} · ${money(d.amount)}`);c.state.draft=null;editingId=null;step=1;c.save();c.navigate('applications');c.toast('Application received. Staff verification is the next step.');trackApplication(application,c);}catch(error){c.toast(error.message||'Check your loan details and try again.');button.disabled=false;button.textContent='Submit application';}};
 const calcForm=document.querySelector('#calculator-form');if(calcForm){const update=()=>{try{const d=formInput(calcForm,inputs(c)),estimate=calculate(d);c.state.draft=d;document.querySelector('#calculator-estimate').innerHTML=estimateCard(d,estimate);c.save();return true;}catch(error){c.toast(error.message);return false;}};calcForm.onsubmit=e=>{e.preventDefault();if(update())c.toast('Your estimate is ready. Try a different term to compare.');};document.querySelector('#use-estimate').onclick=()=>{if(!calcForm.reportValidity()||!update())return;step=2;editingId=null;c.navigate('apply');};}
 const statement=document.querySelector('[data-statement]');if(statement)statement.onclick=()=>{const l=myLoans(c);c.openModal('Statement of account · Preview',`<div class="d-flex align-items-center justify-content-between mb-4"><strong style="font-size:19px;color:var(--green)">SEMCO</strong><span class="pill amber">Sample document</span></div><h3 class="section-title">${esc(c.member.name)}</h3><p class="muted text-small mt-2">${esc(c.member.id)} · As of October 23, 2026</p><dl class="summary-list">${l.map(a=>`<div><dt>${esc(a.product)} · ${a.id}</dt><dd>${money(a.balance)}</dd></div>`).join('')}<div><dt>Total outstanding</dt><dd><strong>${money(l.reduce((s,a)=>s+a.balance,0))}</strong></dd></div></dl><p class="muted text-small mt-4">PDF printing and downloading are presentation only in this prototype.</p>`,`<button class="btn btn-primary" data-close-modal>Close preview</button>`);};
}
